using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace ByteBitReverse;

public class BitReverser
{
    // Lookup table: index i holds the bit-reversal of byte i.
    private static readonly byte[] LookupTable = BuildLookupTable();

    // Nibble-reverse LUT for SIMD shuffle: reversed bits of 0x0–0xF, pre-shifted left by 4.
    private static readonly Vector256<byte> NibbleHi =
        Vector256.Create((byte)0x00,0x80,0x40,0xC0,0x20,0xA0,0x60,0xE0,
                               0x10,0x90,0x50,0xD0,0x30,0xB0,0x70,0xF0,
                               0x00,0x80,0x40,0xC0,0x20,0xA0,0x60,0xE0,
                               0x10,0x90,0x50,0xD0,0x30,0xB0,0x70,0xF0);

    // Nibble-reverse LUT for SIMD shuffle: reversed bits of 0x0–0xF (low nibble result).
    private static readonly Vector256<byte> NibbleLo =
        Vector256.Create((byte)0x00,0x08,0x04,0x0C,0x02,0x0A,0x06,0x0E,
                               0x01,0x09,0x05,0x0D,0x03,0x0B,0x07,0x0F,
                               0x00,0x08,0x04,0x0C,0x02,0x0A,0x06,0x0E,
                               0x01,0x09,0x05,0x0D,0x03,0x0B,0x07,0x0F);

    private static readonly Vector256<byte> Mask0F = Vector256.Create((byte)0x0F);

    private static byte[] BuildLookupTable()
    {
        var table = new byte[256];
        for (int i = 0; i < 256; i++)
        {
            int b = i;
            int r = 0;
            for (int bit = 0; bit < 8; bit++)
            {
                r = (r << 1) | (b & 1);
                b >>= 1;
            }
            table[i] = (byte)r;
        }
        return table;
    }

    public static void ReverseInPlace(Span<byte> data)
    {
        if (Vector256.IsHardwareAccelerated && data.Length >= Vector256<byte>.Count)
        {
            ReverseVector256(data);
        }
        else if (Vector128.IsHardwareAccelerated && data.Length >= Vector128<byte>.Count)
        {
            ReverseVector128(data);
        }
        else
        {
            ReverseScalar(data);
        }
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void ReverseVector256(Span<byte> data)
    {
        var nibbleHi = NibbleHi;
        var nibbleLo = NibbleLo;
        var mask = Mask0F;

        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int lastBlockStart = data.Length - Vector256<byte>.Count;

        while (i <= lastBlockStart)
        {
            var vec = Vector256.LoadUnsafe(ref ptr, (nuint)i);
            var lo = vec & mask;
            var hi = Vector256.ShiftRightLogical(vec.AsUInt16(), 4).AsByte() & mask;
            var result = Vector256.Shuffle(nibbleHi, lo) | Vector256.Shuffle(nibbleLo, hi);
            result.StoreUnsafe(ref ptr, (nuint)i);
            i += Vector256<byte>.Count;
        }

        // Handle remaining bytes with the lookup table.
        ReverseScalar(data.Slice(i));
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static void ReverseVector128(Span<byte> data)
    {
        var nibbleHi = NibbleHi.GetLower();
        var nibbleLo = NibbleLo.GetLower();
        var mask = Mask0F.GetLower();

        ref byte ptr = ref MemoryMarshal.GetReference(data);
        int i = 0;
        int lastBlockStart = data.Length - Vector128<byte>.Count;

        while (i <= lastBlockStart)
        {
            var vec = Vector128.LoadUnsafe(ref ptr, (nuint)i);
            var lo = vec & mask;
            var hi = Vector128.ShiftRightLogical(vec.AsUInt16(), 4).AsByte() & mask;
            var result = Vector128.Shuffle(nibbleHi, lo) | Vector128.Shuffle(nibbleLo, hi);
            result.StoreUnsafe(ref ptr, (nuint)i);
            i += Vector128<byte>.Count;
        }

        ReverseScalar(data.Slice(i));
    }

    private static void ReverseScalar(Span<byte> data)
    {
        ref byte tableRef = ref MemoryMarshal.GetArrayDataReference(LookupTable);
        ref byte ptr = ref MemoryMarshal.GetReference(data);

        for (int i = 0; i < data.Length; i++)
        {
            Unsafe.Add(ref ptr, i) = Unsafe.Add(ref tableRef, Unsafe.Add(ref ptr, i));
        }
    }
}

